{
  "pains": [
    {
      "id": "pain:dirty-data-untrusted-reports",
      "statement": "Our CRM is full of duplicates, half-filled records and wrong tags, so nobody believes the dashboard and I spend my week cleaning instead of building.",
      "element": "b2b:ease_of_doing_business:organization",
      "shape": {
        "surface": "Duplicate contacts and companies, blank or mislabeled fields, lifecycle stages that mean different things to different teams.",
        "operational": "Reports and forecasts are argued over instead of acted on; admins burn recurring hours on hygiene checks and fixing broken workflows; leadership makes calls on numbers staff admit they shade.",
        "personal": "The ops person owns a system everyone blames; their credibility rides on numbers they know are wrong.",
        "personal_note": "Read from the job posting that makes hygiene a standing duty and from Validity's finding that staff fabricate data; no admin in a fetchable source said the personal cost in their own words."
      },
      "workflow": "HubSpot contacts and companies views after list imports and rep entry; the admin runs dedupe and hygiene checks, watches workflow failure logs, then rebuilds leadership dashboards on lead volume and funnel conversion.",
      "type": "felt",
      "confidence": "high",
      "priority": 1,
      "felt_evidence": {
        "kind": "hiring",
        "what": "TDCX posted a HubSpot Administrator role on 2026-09-22 whose duties include regular hygiene checks to prevent and clean duplicates, incomplete records and wrong tags, fixing failed workflows, and keeping metric definitions consistent so teams read reports the same way.",
        "cites": ["src:11"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "A leadership report is challenged because two teams read the same metric differently", "cites": ["src:11"]},
        {"event": "Data quality is blamed for lost revenue or a scrapped campaign", "cites": ["src:13", "src:12"]},
        {"event": "A new team inherits a portal that was set up badly", "cites": ["src:7"]}
      ],
      "who_feels": ["champion", "economic_buyer"],
      "by_role": {
        "champion": {
          "says": [
            {"situation": "when_it_bites", "verbatim": "Run regular hygiene checks to prevent and clean duplicates, incomplete records and wrong tags.", "cites": ["src:11"]},
            {"situation": "venting", "verbatim": "at least half the time people hated it because it had been misconfigured or inexpertly set up", "cites": ["src:7"]}
          ],
          "costs_them": "Recurring hours every week on cleanup and fixing automations instead of building process.",
          "fears": "Being the person whose numbers get thrown out in the board meeting.",
          "dream_outcome": "One record per customer, fields that mean one thing, and a dashboard nobody re-checks in a spreadsheet."
        },
        "economic_buyer": {
          "says": [
            {"situation": "to_their_boss", "verbatim": "75% of respondents say staff fabricates data to tell the story they want decision makers to hear.", "cites": ["src:12"]},
            {"situation": "when_it_bites", "verbatim": "62% of organizations report losing revenue directly due to poor CRM data quality.", "cites": ["src:13"]}
          ],
          "costs_them": "Revenue lost to bad data and decisions made on shaded numbers.",
          "fears": "Paying for a system of record that does not record the truth.",
          "dream_outcome": "Pipeline and funnel numbers they can take to the board without a caveat."
        }
      },
      "relief": {
        "line": "**Numbers stop getting argued.** The weekly report gets read, not re-checked.",
        "says": [],
        "gap": "Searched HN, Trustpilot and job posts; no buyer in a fetchable source described life after a cleanup. Reddit, G2, Capterra and HubSpot Community were blocked."
      },
      "euphoria": {
        "line": "**The CRM is the source of truth.** Ops builds new motions instead of mopping up old data.",
        "says": [],
        "gap": "No fetchable buyer voice describes the year-later state; the TDCX posting names 'single source of truth' only as a goal."
      },
      "segments": ["seg:midmarket", "seg:agency"],
      "feature_ref": "feat:data",
      "cites": ["src:11", "src:7", "src:12", "src:13"]
    },
    {
      "id": "pain:reps-wont-log",
      "statement": "Every field I have to fill in HubSpot is time I am not selling, so I skip it and my manager forecasts off guesses.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "Reps leave activities, notes and deal fields blank or fill them with the minimum to pass validation.",
        "operational": "Pipeline and forecast are built on stale or invented data; managers chase updates instead of coaching.",
        "personal": "Reps feel taxed on their commission time for work that only helps someone else; founders who sell hate the UI but are stuck in it.",
        "personal_note": "From a founder-seller and a sales consultant; no rep quote from 2026 was fetchable."
      },
      "workflow": "After calls and emails, the rep opens the HubSpot deal record, logs the activity, updates stage, amount and required properties before the next call; the manager reviews the pipeline board before forecast.",
      "type": "felt",
      "confidence": "medium",
      "priority": 2,
      "felt_evidence": {
        "kind": "building",
        "what": "A founder who hated CRM data entry built and launched chuff.co, a CRM that works inside email, saying every CRM assumed he'd spend hours in its UI filling out forms (HN, 2025-08-19).",
        "cites": ["src:8"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "Management adds more mandatory deal fields or enforces CRM compliance", "cites": ["src:10"]},
        {"event": "A forecast misses and the CRM shows nothing about why", "cites": ["src:9"]}
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {
        "end_user": {
          "says": [
            {"situation": "venting", "verbatim": "Every CRM I've ever used, assumed I'd spend hours inside its UI, filling out forms and updating fields.", "cites": ["src:8"]},
            {"situation": "when_refusing", "verbatim": "Oh, I'm not updating it because it takes too much of my time. I was doing sales work instead.", "cites": ["src:9"]}
          ],
          "costs_them": "Selling hours spent on admin that does not help them close this quarter.",
          "fears": "Commission clawbacks or manager scrutiny over empty fields.",
          "dream_outcome": "The record updates itself from the call and the inbox; they just sell."
        },
        "champion": {
          "says": [
            {"situation": "to_their_boss", "verbatim": "Every mandatory field is a speed bump between them and their next deal.", "cites": ["src:10"]}
          ],
          "costs_them": "Forecasts built on missing data and time spent nagging reps.",
          "fears": "Adding more rules that produce more fake data.",
          "dream_outcome": "Complete deal records without enforcement."
        }
      },
      "relief": {
        "line": "**No more logging.** Calls and emails land on the deal without anyone typing.",
        "says": [],
        "gap": "No rep in a fetchable source described the after state; vendor blogs claim it but are not buyer voice."
      },
      "euphoria": {
        "line": "**The CRM works for the rep.** It becomes the place they get answers, not the place they report to.",
        "says": [],
        "gap": "No fetchable buyer source; Reddit sales communities were blocked."
      },
      "segments": ["seg:startup", "seg:midmarket"],
      "feature_ref": "feat:agent",
      "cites": ["src:8", "src:9", "src:10"]
    },
    {
      "id": "pain:contact-tier-renewal-trap",
      "statement": "We cut contacts on their advice and still got billed at the old tier because we missed a renewal cut-off nobody told us about.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "Marketing contact tiers auto-upgrade the moment you cross a limit, downgrades only happen at renewal, and contracts auto-renew if you miss a deadline.",
        "operational": "Unplanned spend locked in for a full term; one-off sends or imports push the account up a tier for the year.",
        "personal": "The person who signed the contract eats a surprise bill and has to explain it to finance.",
        "personal_note": "Reviewers name the money; none name a boss conversation, so the personal cost is read from the amounts."
      },
      "workflow": "Marketing imports a list or a workflow marks contacts as marketing in HubSpot; the tier upgrades overnight; at renewal the owner tries to downgrade through support or the contract manager and misses the quote activation window.",
      "type": "felt",
      "confidence": "high",
      "priority": 3,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Trustpilot reviews dated September 2026 describe an account renewing at the old tier after a missed quote activation window, leaving £142 a month billed for unused contacts, and a contract auto-renewing after cancellation was missed by a week.",
        "cites": ["src:2"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "A list import or one-off send crosses the marketing contact limit", "cites": ["src:1", "src:3"]},
        {"event": "Renewal date approaches and the team tries to downgrade or drop components", "cites": ["src:2"]}
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {"situation": "venting", "verbatim": "It renewed at the old tier anyway, because a separate quote had to be activated ten days beforehand", "cites": ["src:2"]},
            {"situation": "venting", "verbatim": "I missed cancelling components of my contract by a week, and it auto-renewed", "cites": ["src:2"]},
            {"situation": "when_refusing", "verbatim": "A three year lock in that auto renews at increased prices", "cites": ["src:3"]}
          ],
          "costs_them": "Hundreds to thousands a month for contacts and seats they do not use, locked until renewal.",
          "fears": "Another surprise line on the invoice they cannot reverse.",
          "dream_outcome": "A bill they can predict and a downgrade they can do themselves."
        }
      },
      "relief": {
        "line": "**The bill matches the plan.** No tier jump they did not choose.",
        "says": [],
        "gap": "Reviewers only describe the failure; none describe a fixed state. HubSpot Community threads on this were blocked to fetch."
      },
      "euphoria": {
        "line": "**They trust the vendor at renewal.** Renewal is a signature, not a negotiation.",
        "says": [],
        "gap": "No buyer source shows this state."
      },
      "segments": ["seg:midmarket", "seg:startup"],
      "feature_ref": null,
      "feature_note": "No HubSpot hub kills this; it is billing policy. What would: a hard cap on marketing contacts and self-serve mid-term downgrades.",
      "cites": ["src:1", "src:2", "src:3"]
    },
    {
      "id": "pain:starter-to-pro-cliff",
      "statement": "The plan goes from tens of dollars to hundreds a month the moment we need one real feature, so we either overpay or leave.",
      "element": "b2b:table_stakes:acceptable_price",
      "shape": {
        "surface": "A huge price gap between Starter and Professional; basic automation, quotes or contact headroom sit behind the higher tier or an extra seat.",
        "operational": "Small teams stall on Starter without automation or pay a multiple of their budget; some migrate to cheaper tools.",
        "personal": "Founders feel trapped by a tool they built their process on and can no longer afford.",
        "personal_note": "From reviewers who say they are leaving or have left."
      },
      "workflow": "A founder or ops lead hits a Starter limit (workflows, quotes, social scheduling, contacts), opens HubSpot pricing to upgrade, sees the Professional price and onboarding fee, and starts comparing alternatives.",
      "type": "felt",
      "confidence": "high",
      "priority": 4,
      "felt_evidence": {
        "kind": "switching",
        "what": "Trustpilot reviewers in September 2026 say they are leaving: one moved to Brevo after finding the next plan up was $800 a month, another is leaving as annual cost rises from €15,000 to €25,000 because quotes now need an extra seat.",
        "cites": ["src:2"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "Team needs workflows, quotes or more contacts than Starter allows", "cites": ["src:2", "src:3"]},
        {"event": "HubSpot changes packaging so an existing feature needs another seat", "cites": ["src:2"]}
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {"situation": "when_comparing", "verbatim": "the next lowest plan is $800 a month!", "cites": ["src:2"]},
            {"situation": "venting", "verbatim": "Recently you have to buy an extra seat just to be able to create quotes", "cites": ["src:2"]},
            {"situation": "when_comparing", "verbatim": "the next category is suddenly $266/seat/month.", "cites": ["src:4"]},
            {"situation": "when_looking", "verbatim": "3000 dollars for hubspot is ridiculous", "cites": ["src:18"]}
          ],
          "costs_them": "A step change in software spend for one feature, or a migration.",
          "fears": "Being priced out of the system their whole funnel runs on.",
          "dream_outcome": "Pay for the next feature they need, not the next tier."
        }
      },
      "relief": {
        "line": "**Growth does not mean a price shock.** The next feature costs about what it is worth.",
        "says": [],
        "gap": "Only people who left describe relief, and they credit the competitor, not a fix."
      },
      "euphoria": {
        "line": "**The CRM grows with them.** They never re-shop it.",
        "says": [],
        "gap": "No buyer source."
      },
      "segments": ["seg:startup"],
      "feature_ref": null,
      "feature_note": "A packaging problem, not a feature gap. What would kill it: a tier between Starter and Professional or feature-level add-ons.",
      "cites": ["src:2", "src:4", "src:18", "src:3"]
    },
    {
      "id": "pain:reporting-forces-exports",
      "statement": "HubSpot cannot answer my attribution and ads questions, so I end up exporting giant CSVs or paying devs to build what we thought we bought.",
      "element": "b2b:ease_of_doing_business:information",
      "shape": {
        "surface": "Attribution, campaign tracking and ads reporting do not answer the questions marketers ask.",
        "operational": "Analysis moves to Excel and Python or to custom development; projects stall.",
        "personal": "The marketer who sold the team on HubSpot owns the gap between the promise and the report.",
        "personal_note": "One commenter says the team was sold on the HubSpot promise and then paused."
      },
      "workflow": "Marketing ops opens HubSpot attribution and ads reports to tie spend to pipeline, cannot cut the data the way leadership wants, exports to CSV for Excel/Python or scopes custom dev.",
      "type": "felt",
      "confidence": "medium",
      "priority": 5,
      "felt_evidence": {
        "kind": "complaining",
        "what": "On HN on 2026-09-26 a commenter says their team spent heavily trying to make HubSpot's ads reporting work, consulted three dev shops, got a $30,000 quote plus enterprise tier pricing, and paused.",
        "cites": ["src:5"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "Leadership asks which campaigns or ads produced pipeline", "cites": ["src:7", "src:5"]}
      ],
      "who_feels": ["champion", "economic_buyer"],
      "by_role": {
        "champion": {
          "says": [
            {"situation": "when_it_bites", "verbatim": "I found myself exporting giant .CSVs to analyze with Excel and Python", "cites": ["src:7"]},
            {"situation": "venting", "verbatim": "attribution modeling and campaign tracking is a poor UX in my opinion", "cites": ["src:7"]}
          ],
          "costs_them": "Hours of manual analysis outside the tool for every attribution question.",
          "fears": "Defending spend without a number they can stand behind.",
          "dream_outcome": "Ask the attribution question inside HubSpot and get an answer leadership accepts."
        },
        "economic_buyer": {
          "says": [
            {"situation": "venting", "verbatim": "Specifically the ads hub or whatever they call the section that is supposed to help with ads reporting.", "cites": ["src:5"]},
            {"situation": "when_refusing", "verbatim": "Once they saw the $30,000 price, months of custom dev work, plus what is the enterprise level thing now?", "cites": ["src:5"]}
          ],
          "costs_them": "Money and months spent shimming reporting the product was sold to provide.",
          "fears": "Paying enterprise prices on top of custom work for the same gap.",
          "dream_outcome": "Spend-to-revenue reporting out of the box."
        }
      },
      "relief": {
        "line": "**No more CSV exports.** Attribution questions get answered where the data lives.",
        "says": [],
        "gap": "HubSpot Community attribution threads were blocked to fetch; no fetchable buyer describes the after state."
      },
      "euphoria": {
        "line": "**Marketing walks in with the revenue number.** Budget fights end.",
        "says": [],
        "gap": "No buyer source."
      },
      "segments": ["seg:midmarket"],
      "feature_ref": "feat:data",
      "cites": ["src:5", "src:7"]
    },
    {
      "id": "pain:per-seat-scaling",
      "statement": "Every new hire is another HubSpot seat, so the bill grows with headcount even when the work does not.",
      "element": "b2b:functional:cost_reduction",
      "shape": {
        "surface": "Per-seat pricing that scales linearly with team size, plus seats needed just to unlock features.",
        "operational": "Software spend grows faster than revenue; teams ration seats or look at self-hosted and AI-administered alternatives.",
        "personal": "The person who owns the budget defends a line that grows every quarter.",
        "personal_note": "Inferred from commenters describing the spend and what they did about it."
      },
      "workflow": "At headcount planning or renewal, the founder or finance lead adds HubSpot seats per new rep or user and compares the total to cheaper or self-hosted options.",
      "type": "felt",
      "confidence": "medium",
      "priority": 6,
      "felt_evidence": {
        "kind": "switching",
        "what": "On HN on 2026-10-03 a commenter says their company got rid of HubSpot, Slack and other tools for self-hosted open source and file-based repos administered with LLMs, and saved on licensing.",
        "cites": ["src:6"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "Team grows and seats are added", "cites": ["src:16"]},
        {"event": "A feature starts requiring an extra seat", "cites": ["src:2"]}
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {"situation": "when_comparing", "verbatim": "Most platforms (like Salesforce, HubSpot, or Jira) charge per-seat.", "cites": ["src:16"]},
            {"situation": "when_looking", "verbatim": "They're expensive, inflexible, and require endless customization.", "cites": ["src:15"]},
            {"situation": "when_looking", "verbatim": "they often felt too complex, restrictive, or expensive as teams grow.", "cites": ["src:19"]}
          ],
          "costs_them": "Linear growth in CRM spend with every hire.",
          "fears": "A cost line that outgrows the value as the company scales.",
          "dream_outcome": "CRM cost tied to value, not headcount."
        }
      },
      "relief": {
        "line": "**Hiring stops raising the CRM bill.** Licensing becomes a rounding error.",
        "says": [
          {"role": "economic_buyer", "verbatim": "we saved quite a bit in licensing fees.", "cites": ["src:6"]}
        ],
        "gap": null
      },
      "euphoria": {
        "line": "**Their data is theirs to use.** AI works on it directly, no SaaS in the way.",
        "says": [],
        "gap": "Only one commenter describes it and in their own paraphrase; not enough for a quote here."
      },
      "segments": ["seg:midmarket", "seg:startup"],
      "feature_ref": null,
      "feature_note": "Pricing model, not a feature. What would kill it: usage- or outcome-based pricing, or free view-only seats.",
      "cites": ["src:6", "src:16", "src:15", "src:19", "src:2"]
    },
    {
      "id": "pain:implementation-needs-partner",
      "statement": "It was so complicated we paid a HubSpot partner, and months and $20k later it still does not work.",
      "element": "b2b:ease_of_doing_business:reduced_effort",
      "shape": {
        "surface": "Setup, integrations and migrations are harder than the sales process implied.",
        "operational": "Teams pay onboarding fees plus partners; go-live slips by months; some abandon and move to another CRM.",
        "personal": "The buyer who pushed for HubSpot owns a sunk cost and a stalled rollout.",
        "personal_note": "From reviewers naming the spend and the delay."
      },
      "workflow": "After signing, the team connects third-party systems and integrations, hires a HubSpot Solutions Partner or agency for setup, and waits on the partner and support through go-live.",
      "type": "felt",
      "confidence": "high",
      "priority": 7,
      "felt_evidence": {
        "kind": "paying",
        "what": "Trustpilot reviewers say they hired a HubSpot partner because the software was too complicated and were $20k in without it working; another spent nearly 20k on a recommended HubSpot expert, had nothing done after 4 months, and moved to Zoho (2026).",
        "cites": ["src:2", "src:3"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "Signing a Professional plan and starting integrations with existing systems", "cites": ["src:3"]},
        {"event": "Sales promised setup was simpler than it is", "cites": ["src:3"]}
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {"situation": "venting", "verbatim": "we hired a partner of Hubspot because of it being such a complicated software.", "cites": ["src:2"]},
            {"situation": "venting", "verbatim": "$20k later still not working right", "cites": ["src:2"]},
            {"situation": "venting", "verbatim": "Spent nearly 20k on this BS", "cites": ["src:3"]}
          ],
          "costs_them": "Partner and onboarding fees on top of licence, plus months without a working system.",
          "fears": "Paying twice: once for HubSpot, once for someone to make it work.",
          "dream_outcome": "Live and integrated in weeks without a partner."
        },
        "champion": {
          "says": [
            {"situation": "when_it_bites", "verbatim": "implementation was considerably more complicated than we had been led to expect", "cites": ["src:3"]},
            {"situation": "when_it_bites", "verbatim": "at the end of 4 months still had nothing done", "cites": ["src:3"]}
          ],
          "costs_them": "Their rollout timeline and their standing with the team.",
          "fears": "Being blamed for a tool that never went live.",
          "dream_outcome": "A setup they can run themselves."
        }
      },
      "relief": {
        "line": "**It is live and connected.** No partner on retainer to keep it running.",
        "says": [],
        "gap": "Reviewers describe failure only; G2 and Capterra, where successful implementers write, were blocked."
      },
      "euphoria": {
        "line": "**They own their stack.** Changes take an afternoon, not a statement of work.",
        "says": [],
        "gap": "No buyer source."
      },
      "segments": ["seg:agency", "seg:midmarket", "seg:startup"],
      "feature_ref": null,
      "feature_note": "No listed feature removes setup complexity; Agent Hub could if it configured portals and integrations, but no source shows it doing so.",
      "cites": ["src:2", "src:3"]
    },
    {
      "id": "pain:ui-churn-clunky",
      "statement": "It is clunky, things that worked keep getting removed, and every update pushes the AI assistant at me.",
      "element": "b2b:ease_of_doing_business:stability",
      "shape": {
        "surface": "Slow, heavy UI, constant betas and feature changes, AI prompts placed to steer users.",
        "operational": "Users relearn screens and lose workflows they relied on; time lost to navigation.",
        "personal": "Daily users feel tricked and worn down by a tool they cannot avoid.",
        "personal_note": "From daily users venting on HN and Trustpilot."
      },
      "workflow": "Reps and marketers in HubSpot all day: moving between records, email attachments and tools, hitting new betas and assistant prompts in the UI.",
      "type": "felt",
      "confidence": "medium",
      "priority": 8,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Dated 2026 complaints: a Trustpilot reviewer on 2026-08-07 says things that previously worked well were removed after 5 years of investment; another on 2026-07-21 calls it clunky and overcomplicated; an HN user on 2026-08-24 says UI updates are designed to push the assistant.",
        "cites": ["src:3", "src:14"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "A UI release removes or moves a feature in daily use", "cites": ["src:3"]},
        {"event": "AI assistant integrations are added to core screens", "cites": ["src:14"]}
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {"situation": "venting", "verbatim": "It is clunky, overcomplicated, and not seamless at all.", "cites": ["src:3"]},
            {"situation": "venting", "verbatim": "they have removed many things that previously worked well", "cites": ["src:3"]},
            {"situation": "venting", "verbatim": "making UI updates designed to force, trick, or confuse me into using their tool when it wasn't my intention", "cites": ["src:14"]},
            {"situation": "venting", "verbatim": "Hubspot is surprisingly horrible", "cites": ["src:17"]}
          ],
          "costs_them": "Time relearning and working around the tool they live in.",
          "fears": "The next update breaking the workflow they rely on.",
          "dream_outcome": "A fast, stable tool that stays out of the way."
        }
      },
      "relief": {
        "line": "**The screen they used yesterday is still there.** Work is fast again.",
        "says": [],
        "gap": "No fetchable buyer describes the after state."
      },
      "euphoria": {
        "line": "**They stop noticing the CRM.** It just works.",
        "says": [],
        "gap": "No buyer source."
      },
      "segments": ["seg:startup", "seg:midmarket", "seg:agency"],
      "feature_ref": null,
      "feature_note": "A product-quality and release-policy problem; no listed hub addresses it.",
      "cites": ["src:3", "src:14", "src:17"]
    },
    {
      "id": "pain:ai-on-bad-data",
      "statement": "We are turning on AI agents that will act on the same messy CRM data our people already do not trust.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "AI recommendations and agents run on incomplete or wrong CRM records.",
        "operational": "Leaders act on AI output that turns out wrong; errors scale faster than manual ones.",
        "personal": null,
